    --SmartThemeBodyColor: rgba(30, 41, 59, 1) !important;
    --SmartThemeEmColor: rgba(100, 116, 139, 1) !important;
    --SmartThemeUnderlineColor: rgba(109, 92, 198, 1) !important;
    --SmartThemeQuoteColor: rgba(42, 122, 123, 1) !important;
    --SmartThemeBlurTintColor: rgba(255, 255, 255, 1) !important;
    --SmartThemeChatTintColor: rgba(255, 255, 255, 0) !important;
    --SmartThemeUserMesBlurTintColor: rgba(224, 236, 250, 1) !important;
    --SmartThemeBotMesBlurTintColor: rgba(255, 255, 255, 1) !important;
    --SmartThemeShadowColor: rgba(24, 38, 66, 0.16) !important;
    --SmartThemeBorderColor: rgba(28, 42, 68, 0.09) !important;
    --blurStrength: 8 !important;
    --lt-accent: #2b7de9;
    --lt-on-accent: #ffffff;
    --lt-scene-display: block;
    --lt-bubble: 74%;
    --lt-glass-hi: rgba(255, 255, 255, 0.92);
    --lt-bubble-hi: rgba(255, 255, 255, 0.9);
