    --lt-blob-1: color-mix(in srgb, #9ec0f2 44%, transparent);
    --lt-blob-2: color-mix(in srgb, #c6c0eb 40%, transparent);
    --lt-blob-3: color-mix(in srgb, #9dd6cf 42%, transparent);
    --lt-blob-4: color-mix(in srgb, #bfd4ee 36%, transparent);
}

/* 2 墨玉 */
:root[data-theme-palette="ink"] {
    color-scheme: dark;
    --SmartThemeBodyColor: rgba(228, 233, 242, 1) !important;
    --SmartThemeEmColor: rgba(143, 155, 176, 1) !important;
    --SmartThemeUnderlineColor: rgba(212, 184, 138, 1) !important;
    --SmartThemeQuoteColor: rgba(134, 178, 177, 1) !important;
